x_comment(x_roommates,"A #$SymmetricBinaryPredicate that relates a #$Person to a #$Person.  <code>(#$roommates PERSON1 PERSON2)</code> means that <code>PERSON1</code> and <code>PERSON2</code> are roommates, i.e. people who share a residence as a matter of convenience, and not as a family unit or romantic couple.  Family members--for example, two siblings--<i>can</i> be roommates, provided that the related roommates do not consider themselves to be \"a family,\" per se.  (A borderline case would be a situation in which a woman moves in with her only child after her husband dies.)  Typically, roommates share the burden of paying rent, utitilies, etc.\n\nNote that #$roommates is only transitive by default, since it is possible (though unlikely) that <code>(#$roommates A B)</code> and <code>(#$roommates B C)</code> but <code>(#$not (#$roommates A C))</code>.  (Consider the case where <code>B</code> has two main residences, with different roommates at each one.)") :- x_cid(a65b12743e607f).
xc_microtheory(a65b12743e607f,x_HumanSocialLifeMt).
