x_comment(x_SendingTangibleMail,"The collection of all events of sending a physical piece of mail via a \nmail delivery system, such as a government or private postal service. A \n#$SendingTangibleMail event is composed of three #$subEvents: a #$Posting event,\nwhere the sender gives a #$MailableObject to a mail delivery system and pays the system\nfor its services, a #$PostalHandlingAndTransport event, where the mail system sorts, \nroutes, and carries the #$MailableObject, and a #$DeliveringMail event, where the \n#$MailableObject is left at its destination. In a #$SendingTangibleMail event, the \n#$MailableObject may be either a letter or parcel. #$SendingTangibleMail events are\n#$performedBy the agent sending the mail. See #$recipientOfPost-Intended for more\ninformation.") :- x_cid(a65b12743e60b4).
